SELECT p.id AS prospect_id, p.company_name, p.legal_name, p.siren, p.siret, p.city, p.source_url, p.activity, p.location, p.website_url, p.phone, p.opportunity, p.state, p.score, p.primary_friction, p.primary_asset, p.primary_cta, p.commercial_eligibility, p.updated_at FROM prospects p WHERE lower(p.company_name) LIKE '%kay juju%' OR lower(p.company_name) LIKE '%bernard%';
SELECT j.id AS job_id, j.kind, j.prospect_id, j.status, j.attempts, j.payload_json, j.last_error, j.created_at, j.updated_at FROM jobs j WHERE j.id IN ('650d916f-fb75-4181-8cd6-e359f18693b7','ff5052a2-fcea-4baf-a6b3-0971d8638b81') OR j.prospect_id IN (SELECT p.id FROM prospects p WHERE lower(p.company_name) LIKE '%kay juju%' OR lower(p.company_name) LIKE '%bernard%') ORDER BY j.created_at;
SELECT jr.job_id, jr.output_json, jr.created_at FROM job_results jr WHERE jr.job_id IN ('650d916f-fb75-4181-8cd6-e359f18693b7','ff5052a2-fcea-4baf-a6b3-0971d8638b81');
SELECT e.id, e.prospect_id, e.actor, e.type, e.payload_json, e.created_at FROM events e WHERE e.prospect_id IN (SELECT p.id FROM prospects p WHERE lower(p.company_name) LIKE '%kay juju%' OR lower(p.company_name) LIKE '%bernard%') ORDER BY e.created_at;
